def encode(message):
    vowels = 'aeiouAEIOU'
    encoded_message = ''

    for char in message:
        if char in vowels:
            next_vowel = (vowels.index(char) + 2) % 5  # Assuming 5 vowels in the alphabet
            if next_vowel == 0:
                next_vowel = 5  # If the next vowel is at the end of the alphabet, wrap around to the beginning
            encoded_char = chr(ord(char) + next_vowel)
        else:
            encoded_char = char.swapcase()
        encoded_message += encoded_char

    return encoded_message

