def minPath(grid: List[List[int]], k: int) -> List[int]:
    N = len(grid)
    directions = [(0, 1), (1, 0), (-1, 0), (0, -1)]
    visited = set()
    min_path_length = float('inf')
    min_path = []

    def dfs(x, y, path_length, path):
        nonlocal min_path_length, min_path

        if path_length == k:
            if path_length < min_path_length:
                min_path_length = path_length
                min_path = path[:]
            print("Found path:", path)  # Add this print statement to print the current path
            return

        if (x, y) in visited:
            return

        visited.add((x, y))

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N:
                dfs(nx, ny, path_length + 1, path + [grid[nx][ny]])

        visited.remove((x, y))

    for i in range(N):
        for j in range(N):
            dfs(i, j, 1, [grid[i][j]])

    return min_path

